import data from "./words.json"

/** Voiceover word timings (generated by scripts/make-transcript.mjs). Scenes are cued off these. */
export const WORDS: { w: string; s: number; e: number }[] = data.words
export const FPS = 30
export const DURATION_FRAMES = Math.ceil(data.duration * FPS)

const norm = (w: string) => w.toLowerCase().replace(/[^a-z0-9]/g, "")

/** Frame at which the `nth` occurrence of `word` starts (or ends) in the voiceover. */
export function cue(word: string, nth = 0, edge: "s" | "e" = "s"): number {
  const hits = WORDS.filter((x) => norm(x.w) === norm(word))
  const hit = hits[nth]
  if (!hit) throw new Error(`cue: "${word}" #${nth} not found in voiceover`)
  return Math.round(hit[edge] * FPS)
}
